1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"unicode/utf8"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// validatedGraphAdjacency is the single authority for whether an existing
67	// in-memory graph is legal, shared by the public ValidateGraph check and every
68	// operation that only reads an existing graph — preview and apply, graph
69	// export, and snapshot builds. It runs every structure rule once and returns
70	// the graph's canonical parent adjacency (sorted, duplicate-free):
71	//
72	//   - a nil map is ErrNotInitialized;
73	//   - dataset names and direct upstream references must be valid UTF-8 (the
74	//     encoding gate runs before anything quotes the names, so an unusable
75	//     upstream is never misreported as a missing one and its original bytes
76	//     stay readable in the error);
77	//   - nil lineage nodes and empty dataset names are rejected;
78	//   - two different dataset names must never point to the same non-nil
79	//     *Lineage record: a batch rewrites a node's relationships in place, so
80	//     one shared record would let an adjustment meant for one dataset silently
81	//     rewrite the other, and the applied graph could never match its report;
82	//   - every direct upstream must be a registered dataset, with the referrer
83	//     and the referenced name both in the error;
84	//   - the parent edges must be acyclic (self-dependency included), with the
85	//     datasets on the cycle named.
86	//
87	// The whole check is read-only: it builds fresh slices from each node's
88	// stored Parents and never touches the caller's nodes or their parent and
89	// child lists, including their order and duplicates. Whether the graph is
90	// legal depends solely on the dataset names and the direct-upstream
91	// relations: an initialized but empty graph is legal.
92	func validatedGraphAdjacency(graph map[string]*Lineage) (adjacency, error) {
93		if graph == nil {
94			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
95		}
96		if err := validateInMemoryNamesUTF8(graph); err != nil {
97			return nil, err
98		}
99		records := make([]GraphDataset, 0, len(graph))
100		for name, entry := range graph {
101			if entry == nil {
102				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
103			}
104			if name == "" {
105				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
106			}
107			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
108		}
109		// A shared record is an aliasing defect no plan can repair: the batch
110		// rewrites surviving nodes in place, so two names on one *Lineage would be
111		// changed together no matter which one the plan names. The original graph
112		// is rejected outright — even when the plan deletes one of the names or
113		// changes nothing — because the deletion must not be executed first and
114		// the graph then judged legal.
115		if first, second, shared := firstSharedLineageNode(graph); shared {
116			return nil, fmt.Errorf("%w: datasets %q and %q share the same lineage node; each dataset must have its own record, otherwise one adjustment would rewrite both", ErrInvalidArgument, first, second)
117		}
118		adj, err := normalizeDatasets(records)
119		if err != nil {
120			return nil, err
121		}
122		return validateGraphAdjacency(adj)
123	}
124	
125	// firstSharedLineageNode reports the earliest pair of dataset names that
126	// point to the same non-nil *Lineage record, or shared == false when every
127	// name has its own record. Nil nodes are skipped (the caller rejects them
128	// separately); pointer identity is the only thing judged, so two independent
129	// records whose fields happen to be identical — or whose parent lists happen
130	// to share a backing slice — are not a conflict.
131	//
132	// The reported pair is deterministic regardless of map iteration order: for
133	// each record referenced by more than one name the two smallest names (UTF-8
134	// byte order, the same ordering every name list in this package uses) form
135	// that record's candidate pair, and the candidate whose first name is
136	// smallest wins. One record referenced by three or more names therefore
137	// reports its two smallest names, and several shared records report the pair
138	// that sorts first overall.
139	func firstSharedLineageNode(graph map[string]*Lineage) (first, second string, shared bool) {
140		byNode := make(map[*Lineage][]string)
141		for name, entry := range graph {
142			if entry == nil {
143				continue
144			}
145			byNode[entry] = append(byNode[entry], name)
146		}
147		for _, names := range byNode {
148			if len(names) < 2 {
149				continue
150			}
151			sort.Strings(names)
152			if !shared || names[0] < first || (names[0] == first && names[1] < second) {
153				first, second, shared = names[0], names[1], true
154			}
155		}
156		return first, second, shared
157	}
158	
159	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
160	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
161	// references), two dataset names sharing one lineage record, missing
162	// upstreams, and cycles. It does not mutate the graph.
163	//
164	// A graph that fails validation cannot be used as the basis for a batch: an
165	// adjustment plan must not be allowed to paper over pre-existing corruption.
166	// This is the same judgment preview, apply, graph export, and snapshot builds
167	// make on the original graph (see validatedGraphAdjacency).
168	func ValidateGraph(graph map[string]*Lineage) error {
169		_, err := validatedGraphAdjacency(graph)
170		return err
171	}
172	
173	// validatePlanNamesUTF8 rejects a plan in which any name that takes part in
174	// the adjustment — a change record's name, one of its direct upstream names,
175	// or a removals entry — is not valid UTF-8. It is the in-memory counterpart
176	// of the raw-literal scan the plan reader runs (checkPlanNameEncoding): a
177	// Plan built directly in Go never passed through that reader, so without
178	// this gate PreviewBatch and ApplyBatch could register datasets the graph
179	// exporter must refuse and produce reports whose JSON silently rewrites the
180	// bad bytes to U+FFFD (two distinct corrupted names would then print as one).
181	//
182	// Plan order is checked as given: the name of record i comes before its
183	// upstreams, and removals follow all changes, so the first reported position
184	// is the earliest offending name the caller submitted. The error names the
185	// field ("name", "upstreams", or "removals"), the zero-based record or array
186	// position, and — for an upstream — its zero-based position inside that
187	// record. The offending name is quoted with %q, which renders the original
188	// bytes as \x escapes rather than replacing them with U+FFFD, so "p\xff" and
189	// "p\xfe" stay distinguishable. The plan is only read, never normalized or
190	// mutated. Register keeps accepting raw Go strings; this gate belongs only
191	// to the batch boundary, where an unusable name would enter a graph and a
192	// report that are promised exportable.
193	func validatePlanNamesUTF8(plan Plan) error {
194		for i, change := range plan.Changes {
195			if !utf8.ValidString(change.Name) {
196				return fmt.Errorf("%w: field %q in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
197					ErrInvalidArgument, "name", i, "changes", change.Name)
198			}
199			for j, upstream := range change.Upstreams {
200				if !utf8.ValidString(upstream) {
201					// Report the unusable name itself, never a missing-upstream
202					// error: the encoding defect takes precedence over whether
203					// the referenced dataset exists in the final graph.
204					return fmt.Errorf("%w: field %q at index %d in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
205						ErrInvalidArgument, "upstreams", j, i, "changes", upstream)
206				}
207			}
208		}
209		for i, name := range plan.Removals {
210			if !utf8.ValidString(name) {
211				return fmt.Errorf("%w: field %q at index %d contains invalid UTF-8 bytes: %q",
212					ErrInvalidArgument, "removals", i, name)
213			}
214		}
215		return nil
216	}
217	
218	// computeBatch validates the graph and plan, then computes the final adjacency
219	// and the diff report. It does not mutate graph. The returned adjacency is the
220	// graph as it will be after the batch; callers that want to commit it should
221	// pass it to applyAdjacency.
222	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
223		// One read of the existing graph settles both its legality and its
224		// canonical relations: the original graph must be legal even when the
225		// plan deletes a bad node or clears a dangling upstream, and the returned
226		// normalized adjacency is the basis the final graph is computed from.
227		original, err := validatedGraphAdjacency(graph)
228		if err != nil {
229			return nil, nil, err
230		}
231	
232		// Check every name the plan carries before anything that would quote it,
233		// hash it, or turn the report into JSON: the file reader already rejects
234		// these at the raw-literal level, but a plan constructed directly through
235		// the Go API bypasses that reader, and without this gate it could register
236		// a dataset whose name cannot be exported — two names differing only in an
237		// invalid byte ("p\xff" vs "p\xfe") would even render identically once the
238		// report is marshaled. This is the in-memory counterpart of the raw scan;
239		// see name_encoding.go.
240		if err := validatePlanNamesUTF8(plan); err != nil {
241			return nil, nil, err
242		}
243	
244		// Validate the plan: empty names and duplicate declarations reject the
245		// whole batch, naming the dataset and the reason.
246		declarations := make(map[string]int, len(plan.Changes))
247		for _, change := range plan.Changes {
248			if change.Name == "" {
249				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
250			}
251			declarations[change.Name]++
252			if declarations[change.Name] > 1 {
253				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
254			}
255		}
256	
257		// Validate removals: empty names, duplicate names, and names also declared
258		// as changes all reject the whole batch with the name and reason.
259		removalDecls := make(map[string]int, len(plan.Removals))
260		for _, name := range plan.Removals {
261			if name == "" {
262				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
263			}
264			removalDecls[name]++
265			if removalDecls[name] > 1 {
266				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
267			}
268			if _, ok := declarations[name]; ok {
269				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
270			}
271		}
272	
273		// Build the final adjacency: start from the original parents, replace each
274		// planned dataset's parents with its normalized upstreams. Being named in
275		// the plan does not by itself make a dataset new or changed — that is
276		// judged below by diffing the original and final graphs, exactly the way a
277		// snapshot comparison judges two versions.
278		final := make(adjacency, len(original)+len(plan.Changes))
279		for name, parents := range original {
280			final[name] = append([]string(nil), parents...)
281		}
282		for name := range removalDecls {
283			delete(final, name)
284		}
285		for _, change := range plan.Changes {
286			final[change.Name] = uniqueSorted(change.Upstreams)
287		}
288	
289		// The final graph obeys the same direct-upstream rule as an existing graph
290		// — every upstream a dataset names must exist in the graph being checked —
291		// but the rule is run here on the FINAL graph, after every add,
292		// replacement, and removal: datasets newly added in the same batch may
293		// reference one another regardless of plan order, while a retained dataset
294		// that still points at a removed name is rejected. The judgment itself is
295		// the shared firstMissingReference, so the two stages can never drift apart
296		// about what counts as a missing direct upstream; the final-graph wording
297		// (and the separate pass over the untouched original graph above) keeps
298		// the stages distinct. Sorted iteration inside the helper makes the
299		// reported (referrer, upstream) pair deterministic.
300		if referrer, referenced, missing := firstMissingReference(final); missing {
301			return nil, nil, finalGraphMissingReferenceError(referrer, referenced)
302		}
303		// The final graph must be acyclic, judged after all replacements.
304		if err := validateAcyclic(final); err != nil {
305			return nil, nil, err
306		}
307	
308		// Classify the dataset-level changes with the shared old -> new rule a
309		// snapshot comparison uses (see diffDatasets): only-in-final is new,
310		// only-in-original is removed, present-on-both is changed only when the
311		// direct upstream set actually differs. Deleting a name that does not
312		// exist is a no-op and is not reported, so a successful plan can be
313		// applied again with empty change and impact lists.
314		newNames, removedNames, changedNames := diffDatasets(original, final)
315	
316		added, removed := diffRelations(original, final)
317		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
318	
319		report := &BatchReport{
320			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
321			NewDatasets:         newNames,
322			ChangedDatasets:     changedNames,
323			RemovedDatasets:     removedNames,
324			AddedRelations:      added,
325			RemovedRelations:    removed,
326			AffectedDownstreams: affected,
327		}
328		// Guarantee non-nil slices so JSON encodes empty lists as [].
329		if report.NewDatasets == nil {
330			report.NewDatasets = []string{}
331		}
332		if report.ChangedDatasets == nil {
333			report.ChangedDatasets = []string{}
334		}
335		if report.RemovedDatasets == nil {
336			report.RemovedDatasets = []string{}
337		}
338		if report.AddedRelations == nil {
339			report.AddedRelations = []Relation{}
340		}
341		if report.RemovedRelations == nil {
342			report.RemovedRelations = []Relation{}
343		}
344		if report.AffectedDownstreams == nil {
345			report.AffectedDownstreams = []string{}
346		}
347		return report, final, nil
348	}
349	
350	// PreviewBatch validates the graph and plan and returns the report WITHOUT
351	// mutating graph. Preview and apply for the same graph and plan produce
352	// identical reports.
353	//
354	// As well as the structural plan rules (empty names, duplicate declarations,
355	// unresolvable upstreams, cycles), every name the plan carries — a change
356	// record's name, any of its direct upstreams, and every removals entry — must
357	// be valid UTF-8 even when the plan was constructed directly in Go instead of
358	// read by UnmarshalPlan. A name that is not valid UTF-8 rejects the whole
359	// batch with ErrInvalidArgument before any dataset could be registered or any
360	// report produced, so a success report can always be marshaled to JSON and an
361	// applied graph can always be exported. See validatePlanNamesUTF8.
362	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
363		report, _, err := computeBatch(graph, plan)
364		return report, err
365	}
366	
367	// ApplyBatch validates the plan, applies it to graph, and returns the report.
368	// On rejection — including a plan that names a dataset, upstream, or removal
369	// with bytes that are not valid UTF-8 — graph is left completely unchanged.
370	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
371		report, final, err := computeBatch(graph, plan)
372		if err != nil {
373			return nil, err
374		}
375		applyAdjacency(graph, final)
376		return report, nil
377	}
378	
379	// applyAdjacency rewrites the in-memory graph to match the final adjacency. It
380	// is the apply path of the shared relationship rule in materializeLineage, the
381	// same rule a graph reader follows: nodes absent from final are removed,
382	// parents are replaced wholesale with independent copies, and children are
383	// rebuilt from the parent edges. Surviving *Lineage records are updated in
384	// place, so node pointers a Go caller already holds expose the new
385	// relationships after the batch returns.
386	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
387		materializeLineage(graph, final)
388	}
389	
390	// diffDatasets is the single authority for classifying dataset-level changes
391	// between two versions of a graph, shared by the batch report (preview and
392	// apply) and the snapshot comparison so both can never disagree about the
393	// rule. Changes are always judged in the direction original -> final:
394	//
395	//   - a dataset present only in final is NEW — even when it arrives carrying
396	//     upstreams, it is never also listed as changed;
397	//   - a dataset present only in original is REMOVED — a removed dataset is
398	//     never also listed as an upstream change;
399	//   - a dataset present on both sides is CHANGED only when its direct
400	//     upstream set actually differs; a dataset whose upstreams were cleared
401	//     still exists (as a root), so it is changed, not removed.
402	//
403	// Names are case-sensitive and compared verbatim; only the name set and each
404	// dataset's normalized upstream set matter, never record order, upstream
405	// order, or duplicate upstreams. Each returned list is sorted by name byte
406	// order and is nil when empty; callers normalize nil to [] for JSON.
407	func diffDatasets(original, final adjacency) (newNames, removedNames, changedNames []string) {
408		for name, finalParents := range final {
409			if originalParents, ok := original[name]; !ok {
410				newNames = append(newNames, name)
411			} else if !stringSliceEqual(originalParents, finalParents) {
412				changedNames = append(changedNames, name)
413			}
414		}
415		for name := range original {
416			if _, ok := final[name]; !ok {
417				removedNames = append(removedNames, name)
418			}
419		}
420		sort.Strings(newNames)
421		sort.Strings(removedNames)
422		sort.Strings(changedNames)
423		return newNames, removedNames, changedNames
424	}
425	
426	// diffRelations returns the directed edges present in final but not original
427	// (added) and present in original but not final (removed). Both lists are
428	// sorted by upstream then downstream.
429	func diffRelations(original, final adjacency) (added, removed []Relation) {
430		origEdges := edgeSet(original)
431		finalEdges := edgeSet(final)
432		for e := range finalEdges {
433			if !origEdges[e] {
434				added = append(added, e)
435			}
436		}
437		for e := range origEdges {
438			if !finalEdges[e] {
439				removed = append(removed, e)
440			}
441		}
442		sortRelations(added)
443		sortRelations(removed)
444		return added, removed
445	}
446	
447	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
448	func edgeSet(adj adjacency) map[Relation]bool {
449		set := make(map[Relation]bool)
450		for downstream, parents := range adj {
451			for _, upstream := range parents {
452				set[Relation{Upstream: upstream, Downstream: downstream}] = true
453			}
454		}
455		return set
456	}
457	
458	// sortRelations sorts by upstream then downstream.
459	func sortRelations(rels []Relation) {
460		sort.Slice(rels, func(i, j int) bool {
461			if rels[i].Upstream != rels[j].Upstream {
462				return rels[i].Upstream < rels[j].Upstream
463			}
464			return rels[i].Downstream < rels[j].Downstream
465		})
466	}
467	
468	// affectedDownstreams computes the impact set: starting from the seed datasets
469	// (new, actually changed, or actually removed), follow downstream (children)
470	// edges in BOTH the original and the final graphs. Datasets that are
471	// themselves seeds are excluded from the output; every other reachable dataset
472	// is included once.
473	//
474	// Walking both graphs matters when relations are deleted: a dataset that was
475	// reachable downstream before the change (and thus loses a lineage path) is
476	// still affected even if the edge is gone in the final graph. Removed datasets
477	// are seeds too, so a downstream that lost its upstream node is counted.
478	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
479		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
480		for _, name := range newNames {
481			seeds[name] = true
482		}
483		for _, name := range changedNames {
484			seeds[name] = true
485		}
486		for _, name := range removedNames {
487			seeds[name] = true
488		}
489	
490		origChildren := invertAdjacency(original)
491		finalChildren := invertAdjacency(final)
492	
493		seen := make(map[string]bool)
494		queue := make([]string, 0, len(seeds))
495		for seed := range seeds {
496			queue = append(queue, seed)
497		}
498		for len(queue) > 0 {
499			node := queue[0]
500			queue = queue[1:]
501			for _, child := range origChildren[node] {
502				if !seen[child] {
503					seen[child] = true
504					queue = append(queue, child)
505				}
506			}
507			for _, child := range finalChildren[node] {
508				if !seen[child] {
509					seen[child] = true
510					queue = append(queue, child)
511				}
512			}
513		}
514	
515		out := make([]string, 0, len(seen))
516		for name := range seen {
517			if !seeds[name] {
518				out = append(out, name)
519			}
520		}
521		sort.Strings(out)
522		return out
523	}
524	
525	// invertAdjacency maps each dataset to the datasets that depend on it (its
526	// children), with each child list sorted by name.
527	func invertAdjacency(adj adjacency) map[string][]string {
528		children := make(map[string][]string, len(adj))
529		for name, parents := range adj {
530			for _, parent := range parents {
531				children[parent] = append(children[parent], name)
532			}
533		}
534		for name := range children {
535			sort.Strings(children[name])
536		}
537		return children
538	}
539	
540	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
541	// records with non-nil upstream lists.
542	func adjacencyToDatasets(adj adjacency) []GraphDataset {
543		names := make([]string, 0, len(adj))
544		for name := range adj {
545			names = append(names, name)
546		}
547		sort.Strings(names)
548		ds := make([]GraphDataset, 0, len(names))
549		for _, name := range names {
550			parents := adj[name]
551			if parents == nil {
552				parents = []string{}
553			}
554			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
555		}
556		return ds
557	}
558	
559	// stringSliceEqual reports whether a and b contain the same strings in the
560	// same order. Both are expected to be sorted and duplicate-free.
561	func stringSliceEqual(a, b []string) bool {
562		if len(a) != len(b) {
563			return false
564		}
565		for i := range a {
566			if a[i] != b[i] {
567				return false
568			}
569		}
570		return true
571	}
572	
573	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
574	// The graph must satisfy every structure rule a reader enforces; nil nodes,
575	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
576	// references), missing upstreams, and dependency cycles (including a dataset
577	// that lists itself) reject the export with no bytes returned, so a successful
578	// result can always be read back with UnmarshalGraphFile. The check is
579	// read-only: the in-memory graph is never modified.
580	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
581		adj, err := validatedGraphAdjacency(graph)
582		if err != nil {
583			return nil, err
584		}
585		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
586		return json.MarshalIndent(gf, "", "  ")
587	}
588	
589	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
590	// graph (parents and derived children). The graph is checked with the same
591	// structural rules a snapshot enforces (empty names, duplicate datasets,
592	// missing upstreams, and cycles); a structurally invalid graph is rejected so
593	// it cannot be used as the basis for a batch. As in a snapshot, a known field
594	// declared twice within the same object — datasets in the graph object, name
595	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
596	// even when the duplicates carry identical values.
597	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
598		if err := checkGraphFileDuplicateFields(data); err != nil {
599			return nil, err
600		}
601		// Decode the graph content through the one pipeline a snapshot's embedded
602		// graph also uses (see graph_document.go): the raw name-encoding gate, a
603		// single JSON decode, then the shared structure rules. A corrupted name
604		// literal, an unresolvable upstream, or a cycle is therefore judged by
605		// exactly one implementation for both documents.
606		adj, err := readGraphDocument(data, "invalid graph JSON")
607		if err != nil {
608			return nil, err
609		}
610		// Rebuild children from the parent edges so the in-memory graph is
611		// consistent regardless of how the file was produced.
612		return lineageFromAdjacency(adj), nil
613	}
614	
615	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
616	// duplicate declarations) is validated later by computeBatch so that preview
617	// and apply share identical rejection behavior.
618	//
619	// A known field declared twice within the same object — changes or removals
620	// at the top level, name or upstreams inside one change record — is
621	// ambiguous: the reader would silently keep only the last declaration and
622	// drop the earlier adjustment. The whole plan is refused instead, even when
623	// the duplicates carry identical values, one is null, or the surviving value
624	// is a legal empty list. Field names are recognized the same way the decoder
625	// resolves them (after JSON unescaping, with Unicode case folding), so a
626	// second declaration spelled "Changes" or "changes" still collides;
627	// dataset names themselves stay case-sensitive. Unknown fields keep their
628	// ignore-everything behavior and may repeat freely.
629	//
630	// Every name that takes part in the adjustment — each change record's name,
631	// every upstreams entry, and every removals entry — must also survive
632	// decoding exactly as written: a raw string literal carrying bytes that are
633	// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
634	// silently rewritten to U+FFFD by the decoder, and the corrupted name could
635	// then collide with a genuinely different dataset (a removals entry meant
636	// for no one could delete the dataset really named "�"). The whole plan is
637	// refused instead, naming the field and the zero-based record or array
638	// position, even when the corrupted name would only have matched a dataset
639	// that does not exist. A genuine "�", correctly paired surrogate escapes,
640	// and names that merely look like escapes (a backslash before an ordinary
641	// letter) stay legal; unknown fields and their nested strings are not
642	// checked. The raw scan is shared with the graph readers and lives in
643	// name_encoding.go; this file only supplies the plan document scope.
644	func UnmarshalPlan(data []byte) (Plan, error) {
645		var p Plan
646		if err := checkPlanDuplicateFields(data); err != nil {
647			return p, err
648		}
649		if err := json.Unmarshal(data, &p); err != nil {
650			return p, fmt.Errorf("invalid plan JSON: %w", err)
651		}
652		if err := checkPlanNameEncoding(data); err != nil {
653			return Plan{}, err
654		}
655		return p, nil
656	}
657	
658	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
659	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
660	// file's own location: datasets may be declared only once in the top-level
661	// graph object, and name and upstreams only once in each dataset record. The
662	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
663	// so preview, apply, and snapshot can never disagree about a graph that
664	// repeats a known field.
665	func checkGraphFileDuplicateFields(data []byte) error {
666		return runFieldScan(data, func(dec *json.Decoder) error {
667			return checkGraphObject(dec, "at the top level of the graph")
668		})
669	}
670	
671	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
672	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
673	// locations: changes or removals at the top level, and name or upstreams
674	// inside each change record. A change record carries the same fields as a
675	// dataset record, so both use the shared datasetRecordFields scope and a plan
676	// can never be judged differently from the other documents about what counts
677	// as a repeated field.
678	func checkPlanDuplicateFields(data []byte) error {
679		return runFieldScan(data, func(dec *json.Decoder) error {
680			return checkObjectFields(dec, "at the top level of the plan", []knownField{
681				{name: "changes", nested: func(dec *json.Decoder) error {
682					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
683						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
684					})
685				}},
686				{name: "removals"},
687			})
688		})
689	}
