355			s += fmt.Sprintf("%s:{P:%v C:%v} ", name, e.Parents, e.Children)
356		}
357		// Include non-roots too, sorted by name so the dump is deterministic
358		// regardless of map iteration order.
359		var nonRoots []string
360		for name, e := range graph {
