func TestRegisterRejectionWithSharedStorageAtomic(t *testing.T) {
	t.Run("missing upstream", func(t *testing.T) {
		graph, heldA, heldB, heldC, heldD := sharedCDList()
		err := Register(graph, Dataset{Name: "C"}, []string{"B", "ghost"})
