// Duplicate parent names count as one relationship, and the stored lineage is
// independent of the caller's slice: mutating parents after Register returns
// does not affect the graph.
//
// The relationship change is determined solely by the submitted dataset name
// and its new upstreams. A hand-constructed graph may have two independent
// Lineage records whose Children (or Parents) slices share one backing array,
// overlap in a sub-slice window, or carry spare capacity another record's
// list occupies. Such a graph is legal as long as names correspond and no
// reference or cycle is missing, so Register never edits those name lists in
// place: every affected child list is rebuilt as an independent slice from a
// snapshot of the parent edges. Removing one upstream can therefore never
// shift or duplicate names another record's list shares, and adding one can
// never overwrite a name living in spare capacity. Records of datasets not
// involved in the change keep their previous contents.
//
// Registration is atomic. If any parent is missing or the resulting graph
// would contain a cycle (including a dataset depending on itself, directly or
// through other nodes), no node and no parent/child record is changed. Cycle
// validation uses the relationships as they will be AFTER the replacement, so
// an edge removed by this registration cannot make a legal change fail.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if graph == nil {
		return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
	}
	if dataset.Name == "" {
		return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
	}

	// Normalize on a copy: dedupe (duplicates are one relationship), sort,
	// and detach from the caller's backing array.
	wanted := uniqueSorted(parents)
	for _, parent := range wanted {
		entry, ok := graph[parent]
		if !ok {
			return fmt.Errorf("%w: upstream dataset %q is not registered", ErrNotFound, parent)
		}
		if entry == nil {
			return fmt.Errorf("%w: upstream dataset %q points to a nil lineage node", ErrInvalidArgument, parent)
		}
	}

	// Snapshot every relationship this commit can observe, on independent
	// slices, BEFORE mutating anything. Validation and commit both read these
	// copies rather than the live lists: two records in a hand-built graph may
	// share one backing array (or overlap a window of it), so reading a list
	// after another list was rewritten could observe corrupted names.
	current, existed := graph[dataset.Name]
	var oldParents, oldChildren []string
	if current != nil {
		oldParents = append(oldParents, current.Parents...)
		// Normalize the preserved downstream on the copy as well, so a
		// hand-edited unsorted or duplicated list is repaired without an
		// in-place write.
		oldChildren = uniqueSorted(current.Children)
	}

	// Adding an edge dataset -> parent creates a cycle exactly when parent
	// can already reach the dataset by following parent edges in the
	// post-replacement graph.
	for _, parent := range wanted {
		if reachesAfterReplacement(graph, dataset.Name, wanted, parent, dataset.Name) {
			return fmt.Errorf("%w: dataset %q cannot depend on %q, it would reach itself", ErrCycle, dataset.Name, parent)
		}
	}

	// ---- All checks passed; commit below this line. ----
	//
	// No list is edited in place. In-place removal (append(list[:i],
	// list[i+1:]...)) shifts the shared backing array and corrupts every
	// other record whose list shares that storage — the removed name lands in
	// a neighbor's window and a kept name can duplicate or vanish. In-place
	// insertion is equally unsafe when the list has spare capacity another
	// record's list occupies. Instead, rebuild each affected child list from a
	// fresh snapshot of the parent edges.

	if !existed || current == nil {
		current = &Lineage{Dataset: dataset.Name}
		graph[dataset.Name] = current
	}
	current.Parents = wanted
	current.Children = oldChildren

	newSet := toSet(wanted)
	oldSet := toSet(oldParents)

	// Dropped upstreams lose the dataset as a child; rebuild their child list
	// independently from a snapshot of their parents so the removal cannot
	// move names shared by another record's list.
	for _, oldParent := range oldParents {
		if newSet[oldParent] {
			continue // relationship is kept
		}
		if entry := graph[oldParent]; entry != nil {
			entry.Children = childrenOf(graph, oldParent, dataset.Name)
		}
	}

	// New upstreams gain the dataset as a child. Every kept relationship is
	// rebuilt too: the old parent's stored list may have been sharing storage
	// with a just-rewritten list, so it is rebuilt from the same edge
	// snapshot rather than trusted or edited in place.
	handled := make(map[string]bool, len(wanted))
	for _, parent := range wanted {
		if handled[parent] {
			continue
		}
		handled[parent] = true
		if entry := graph[parent]; entry != nil {
			entry.Children = childrenOf(graph, parent, dataset.Name)
		}
	}

	return nil
}

// childrenOf rebuilds parent's child list from a snapshot of every node's
// parents: it contains, once and in name byte order, exactly the datasets
// that currently list parent as a direct upstream. overrideNode's parents are
// taken as overrideParents (the relationships just committed), so the rebuilt
// list already reflects this registration without re-reading a list that may
// share backing storage with it. All snapshots are independent copies; the
// graph is only read, never mutated through them.
func childrenOf(graph map[string]*Lineage, parent, overrideNode string, overrideParents ...[]string) []string {
	var children []string
	for name, entry := range graph {
		if entry == nil {
			continue
		}
		parents := entry.Parents
		if name == overrideNode && len(overrideParents) > 0 {
			parents = overrideParents[0]
		}
		for _, candidate := range parents {
			if candidate == parent {
				children = append(children, name)
				break
			}
		}
	}
	return uniqueSorted(children)
}

